const seedDatabase = async () => {
  try {
    console.log("Connecting to MongoDB...");
    await mongoose.connect(MONGODB_URI);
    console.log("Connected!");

    const toolSchema = new mongoose.Schema(
      {
        name: { type: String, required: true },
        slug: { type: String, required: true, unique: true },
        shortDescription: String,
        description: String,
        category: String,
        subCategory: String,
        pricing: String,

        pricingDetails: {
          monthlyPrice: Number,
          yearlyPrice: Number,
          currency: String,
        },

        websiteUrl: String,
        imageUrl: String,
        logo: String,
        rating: Number,
        totalReviews: Number,

        features: [String],
        pros: [String],
        cons: [String],
        tags: [String],
        searchableKeywords: [String],
        searchAliases: [String],
        useCases: [String],
        industries: [String],
        integrations: [String],
        languages: [String],
        supportedCountries: [String],
        platforms: [String],

        aiType: String,
        toolPurpose: String,
        difficultyLevel: String,
        freeTrialAvailable: { type: Boolean, default: false },

        views: { type: Number, default: 0 },
        clickCount: { type: Number, default: 0 },
        shareCount: { type: Number, default: 0 },
        bookmarkCount: { type: Number, default: 0 },
      },
      { timestamps: true },
    );

    const Tool = mongoose.models.Tool || mongoose.model("Tool", toolSchema);

    console.log("Clearing old data...");
    await Tool.deleteMany({});

    // ✅ Chunk function
    const chunkArray = (arr, size) => {
      const chunks = [];
      for (let i = 0; i < arr.length; i += size) {
        chunks.push(arr.slice(i, i + size));
      }
      return chunks;
    };

    const chunks = chunkArray(aiTools, 50); // 50 per batch

    console.log(`Total tools: ${aiTools.length}`);
    console.log(`Chunks: ${chunks.length}`);

    for (let i = 0; i < chunks.length; i++) {
      try {
        console.log(`Inserting batch ${i + 1}/${chunks.length}`);

        await Tool.insertMany(chunks[i], {
          ordered: false, // ⚡ one fail won't stop batch
        });
      } catch (err) {
        console.log(`Batch ${i + 1} partial error ignored`);
      }
    }

    console.log("🎉 All tools inserted successfully!");
    process.exit(0);
  } catch (error) {
    console.error("❌ Seed Error:", error);
    process.exit(1);
  }
};

seedDatabase();
